FORB = ("uu", "ttttt", "ututtu")
def T(x):
    return x ^ ((x << 1) | (x << 2))
def U(x):
    return T(x) ^ 1
def P(x):
    return T(2 * x + 1) >> 1
def A(x):
    return T(x) >> 2
G = {'t': T, 'u': U, 'p': P}
GI = {'T': 't', 'U': 'u', 'P': 'p'}
def S_of(v):
    m = v & 3
    if m == 0:
        return 't'
    if m == 1:
        return 'u'
    return 'p'
def Q_of(z):
    m = z & 15
    if m == 7:
        return 'u'
    if m == 11:
        return 't'
    return None
def F_of(z):
    q = Q_of(z)
    if q is None:
        return None
    return G[q](A(z))
def omega(qmod, g):
    if qmod == 0 and g == 't':
        return 1
    if qmod == 1 and g == 'u':
        return 1
    return 0
def Hword(rho, word):
    z = rho
    out = []
    for g in word:
        z = G[g](z)
        out.append(S_of(z))
    return ''.join(out)
def Wstar_of(rho, word):
    z = rho
    w = 0
    counts = [0] * 48
    LIX = {'t': 0, 'u': 1, 'p': 2}
    for g in word:
        r = z & 15
        counts[r * 3 + LIX[g]] += 1
        w += omega(r, g)
        z = G[g](z)
    return w, counts, z
def beta_terms(xs, branches, s):
    terms = []
    for t in range(1, s + 1):
        a = xs[t - 1]
        for _ in range(s - t + 1):
            a = A(a)
        if t == s:
            ell = branches[t - 1]
        else:
            y = xs[t]
            for _ in range(s - t - 1):
                y = A(y)
            ell = S_of(y)
        terms.append({'t': t, 'L': s - t + 2, 'old_mod16': a & 15, 'ell': ell, 'cost': omega(a & 15, ell)})
    return terms
def admissible(w):
    return not any(f in w for f in FORB)
print("k1 helpers ok")

