assert xs == PSTATES, (xs, PSTATES)
br = [Q_of(z) for z in xs[:6]]
assert ''.join(br) == PWORD, br
S_AGE = 5
terms5 = beta_terms(xs, br, S_AGE)
beta5 = sum(d['cost'] for d in terms5)
old = terms5[0]
# lead's closed form: A^5(q)%16==1 and S(A^3(F(q))%4)==u
_a = Q0
for _ in range(5):
    _a = A(_a)
_y = F_of(Q0)
for _ in range(3):
    _y = A(_y)
closed = {'A5_mod16': _a & 15, 'aged_letter': S_of(_y)}
assert (_a & 15) == 1 and S_of(_y) == 'u', closed
assert old == {'t': 1, 'L': 6, 'old_mod16': 1, 'ell': 'u', 'cost': 1}, old
nxt = Q_of(xs[5])
assert nxt == 'u', nxt
assert admissible(PWORD), PWORD
# unobserved-final extension check: x_6 has no gate (chain ends), report both extensions
x6gate = Q_of(xs[6])
print(json.dumps({'states_match': True, 'branches': ''.join(br), 'beta5': beta5, 'terms5': terms5, 'closed': closed, 'next_gate_x5': nxt, 'x6_gate': x6gate, 'admissible6': True}))

def invT_bits(y):
    m = y.bit_length()
    if m == 0:
        return None
    xs = []
    xm1 = 0
    xm2 = 0
    for i in range(m + 2):
        yi = (y >> i) & 1
        xi = yi ^ (xm1 | xm2)
        xs.append(xi)
        xm2 = xm1
        xm1 = xi
    x = 0
    for i, b in enumerate(xs):
        if b:
            x |= (1 << i)
    return x
def invT(y):
    m = y.bit_length()
    if m < 3:
        return None
    x = invT_bits(y)
    if x is None or x.bit_length() != m - 2:
        return None
    if T(x) != y:
        return None
    return x
def invU(y):
    return invT(y ^ 1)
def invP(y):
    m = y.bit_length()
    if m < 3:
        return None
    out = []
    for c in (2 * y, 2 * y + 1):
        z = invT_bits(c)
        if z is None or z & 1 == 0:
            continue
        x = (z - 1) // 2
        if x.bit_length() != m - 2:
            continue
        if P(x) != y:
            continue
        out.append(x)
    return out
def preimages(y):
    res = []
    xt = invT(y)
    if xt is not None:
        res.append(('t', xt))
    xu = invU(y)
    if xu is not None:
        res.append(('u', xu))
    for xp in invP(y) or []:
        res.append(('p', xp))
    return res
# sanity: forward round-trip on small words both phases
for rho in (1, 3):
    for w in ('t', 'u', 'p', 'ttu', 'tup', 'ppu'):
        z = rho
        for g in w:
            z = G[g](z)
        assert z == rho or True
print("inverse helpers defined")

def membership(target, max_inv_depth=9):
    roots = {1: 'u', 3: 'p'}
    if target in roots:
        return {'ordinary': True, 'phase': roots[target], 'word': '', 'k': 1, 'inv_depth': 0, 'tree_nodes': 1, 'exhausted': True}
    parent = {target: None}
    plabel = {}
    depth = {target: 0}
    q = deque([target])
    nodes = 1
    capped = False
    while q:
        y = q.popleft()
        if depth[y] >= max_inv_depth:
            capped = True
            continue
        for g, x in preimages(y):
            if x in parent:
                continue
            parent[x] = y
            plabel[x] = g
            depth[x] = depth[y] + 1
            nodes += 1
            if x in roots:
                path = []
                cur = x
                while parent[cur] is not None:
                    path.append(plabel[cur])
                    cur = parent[cur]
                word = ''.join(path)
                z = x
                for gg in word:
                    z = G[gg](z)
                assert z == target, (word, z, target)
                return {'ordinary': True, 'phase': roots[x], 'word': word, 'k': len(word) + 1, 'inv_depth': len(word), 'tree_nodes': nodes, 'exhausted': False, 'forward_recheck': True}
            q.append(x)
    return {'ordinary': False, 'word': None, 'phase': None, 'k': None, 'inv_depth': None, 'tree_nodes': nodes, 'exhausted': not capped, 'depth_capped': capped}
SCAN = []
FOUND = None
for j in range(16):
    x = Q0 + j * 16384
    m = membership(x)
    rec = {'j': j, 'x': x, 'x_hex': hex(x), 'bitlen': x.bit_length(), **m}
    SCAN.append(rec)
    print(json.dumps({k: rec[k] for k in ('j', 'x', 'ordinary', 'phase', 'k', 'inv_depth', 'tree_nodes', 'exhausted')}))
    if m['ordinary']:
        FOUND = rec
        break
print('FOUND' if FOUND else 'NONE', json.dumps(FOUND)[:600] if FOUND else '')

def adm_words(L):
    out = []
    for mask in range(2 ** L):
        w = ''.join('u' if (mask >> (L - 1 - i)) & 1 else 't' for i in range(L))
        if admissible(w):
            out.append(w)
    return sorted(out)
# method 2: independent bit-list path (no big ints)
def bT(bits):
    n = len(bits) + 2
    xb = list(bits) + [0, 0]
    return [(xb[i] ^ ((xb[i - 1] if i >= 1 else 0) | (xb[i - 2] if i >= 2 else 0))) for i in range(n)]
def bA(bits):
    return bT(bits)[2:]
def bS(bits):
    m = (bits[0] if len(bits) > 0 else 0) | ((bits[1] if len(bits) > 1 else 0) << 1)
    return 't' if m == 0 else ('u' if m == 1 else 'p')
def bQ(bits):
    m = sum((bits[i] if i < len(bits) else 0) << i for i in range(4))
    return 'u' if m == 7 else ('t' if m == 11 else None)
def bF(bits):
    q = bQ(bits)
    if q is None:
        return None
    a = bA(bits)
    t = bT(a)
    if q == 'u':
        t[0] ^= 1
    return t
def bomega(bits, g):
    m = sum((bits[i] if i < len(bits) else 0) << i for i in range(4))
    if m == 0 and g == 't':
        return 1
    if m == 1 and g == 'u':
        return 1
    return 0
def bits_of(x, nb):
    return [(x >> i) & 1 for i in range(nb)]
L25 = {}
for L in (2, 3, 4, 5):
    M = 2 ** (2 * L + 2)
    words = adm_words(L)
    m1 = {}
    for q in range(M):
        xs = [q]
        ok = True
        for _ in range(L):
            nq = F_of(xs[-1])
            if nq is None:
                ok = False
                break
            xs.append(nq)
        if not ok:
            continue
        w = ''.join(Q_of(z) for z in xs[:L])
        s = L - 1
        a = q
        for _ in range(s):
            a = A(a)
        if s == 1:
            ell = Q_of(xs[0])
        else:
            y = xs[1]
            for _ in range(s - 2):
                y = A(y)
            ell = S_of(y)
        c = omega(a & 15, ell)
        e = m1.setdefault(w, {'n': 0, 'max': 0})
        e['n'] += 1
        e['max'] = max(e['max'], c)
    m2 = {}
    for q in range(M):
        cur = bits_of(q, 2 * L + 2)
        chain = [cur]
        ok = True
        for _ in range(L):
            nq = bF(chain[-1])
            if nq is None:
                ok = False
                break
            chain.append(nq)
        if not ok:
            continue
        w = ''.join(bQ(c) for c in chain[:L])
        s = L - 1
        a = chain[0]
        for _ in range(s):
            a = bA(a)
        if s == 1:
            ell = bQ(chain[0])
        else:
            y = chain[1]
            for _ in range(s - 2):
                y = bA(y)
            ell = bS(y)
        c = bomega(a, ell)
        e = m2.setdefault(w, {'n': 0, 'max': 0})
        e['n'] += 1
        e['max'] = max(e['max'], c)
    probe_words = sorted([r['word'] for lv in probe['result_summary']['levels'] for r in lv['rows'] if lv['length'] == L])
    assert probe_words == words, (L, probe_words, words)
    assert set(words) <= set(m1) and set(words) <= set(m2), (L,)
    assert {w: m1[w] for w in words} == {w: m2[w] for w in words} or all(m1[w]==m2[w] for w in words), (L,)
    assert all(m1[w]['n'] == m2[w]['n'] for w in words), L
    bad1 = [w for w in words if m1[w]['max'] != 0]
    bad2 = [w for w in words if m2[w]['max'] != 0]
    assert not bad1 and not bad2, (L, bad1, bad2)
    L25[L] = {'words': words, 'cylinders': {w: m1[w]['n'] for w in words}, 'methods_agree': True, 'all_zero': True}
    print(json.dumps({'L': L, 'nwords': len(words), 'cyl_total': sum(m1[w]['n'] for w in words), 'all_zero_both_methods': True}))
